-- Carga das propostas de cursos — catálogo 2026 (Fábrica de Cursos).
--
-- Regras aplicadas nesta carga:
--   * TRILHA CIBERSEGURANÇA / CLOUD E DEVOPS / DADOS / DESENVOLVIMENTO
--     -> mapeada para a área correspondente e registrada como 'submetida'
--        (exibida como "Registrada").
--   * TRILHA GRADUAÇÃO / MBA / PÓS-GRADUAÇÃO
--     -> também registrada como 'submetida', com a área mapeada atribuída
--        por tema. A carga horária é opcional: será definida depois que a
--        pesquisa pública validar o curso (workload_hours fica nulo).
--   * Justificativas curtas ("SOLICITAÇÃO CENTRO UNIVERSITÁRIO", "MAGNO
--     APAGOU") são substituídas por texto público nesta carga.
--   * Criador (created_by): primeiro perfil admin ou gestor existente.
--
-- A carga é idempotente pela coluna title (deduplicação case-insensitive) e
-- pode ser executada mais de uma vez sem duplicar propostas.
--
-- Execute pelo Supabase SQL Editor (roda com privilégio que ignora RLS).

begin;

do $$
begin
  if not exists (select 1 from public.profiles where role in ('admin', 'gestor')) then
    raise exception 'Crie um perfil admin ou gestor antes de executar esta carga.';
  end if;
end;
$$;

with source as (
  select *
  from jsonb_to_recordset($proposals$
[
  {"title": "Testes de Intrusão - Pentest Web e Exploração de Aplicações", "hours": 40, "area": "Segurança Cibernética", "justification": "Com a transformação digital acelerada, sistemas de e-commerce, APIs de integração, portais de clientes e plataformas SaaS tornaram-se o coração operacional das empresas. Por estarem expostas publicamente na internet 24 horas por dia, 7 dias por semana, as aplicações web transformaram-se no principal vetor de ataque utilizado por cibercriminosos para invadir infraestruturas internas e sequestrar dados confidenciais.", "draft": false},
  {"title": "Análise Forense de Sistemas Operacionais", "hours": 40, "area": "Segurança Cibernética", "justification": "O aumento dos incidentes de segurança e crimes cibernéticos exige profissionais capacitados para identificar, coletar e analisar evidências digitais.", "draft": false},
  {"title": "DevSecOps: Integração de Segurança no Pipeline CI/CD", "hours": 40, "area": "Segurança Cibernética", "justification": "Integrar a segurança de forma automatizada em todas as etapas do ciclo de vida do software, eliminando gargalos e corrigindo falhas antes que cheguem à produção", "draft": false},
  {"title": "SOC - Engenharia de Detecção e Criação de Regras SIGMA/YARA", "hours": 40, "area": "Segurança Cibernética", "justification": "O curso SOC – Engenharia de Detecção e Criação de Regras SIGMA/YARA é fundamental para capacitar profissionais na identificação e resposta a ameaças cibernéticas em ambientes corporativos. A utilização de regras SIGMA e YARA permite padronizar e automatizar a detecção de incidentes, aumentando a eficiência dos Centros de Operações de Segurança (SOC). Essa formação contribui para fortalecer a defesa contra ataques, garantir conformidade com normas de segurança e preparar especialistas para atuar em um mercado cada vez mais exigente em proteção de dados e infraestrutura crítica.", "draft": false},
  {"title": "SOC - SIEM e Análise de Logs de Segurança", "hours": 40, "area": "Segurança Cibernética", "justification": "O curso SOC – SIEM e Análise de Logs de Segurança é essencial para preparar profissionais na gestão e monitoramento de eventos de segurança em ambientes corporativos. O uso de plataformas SIEM, aliado à análise de logs, permite identificar incidentes, correlacionar eventos e responder de forma rápida e eficaz a ameaças cibernéticas. Essa capacitação fortalece a atuação dos Centros de Operações de Segurança (SOC), garante maior proteção de dados e infraestrutura crítica, além de atender às exigências de conformidade e boas práticas internacionais em segurança da informação.", "draft": false},
  {"title": "Analista de SOC", "hours": 40, "area": "Segurança Cibernética", "justification": "Com o volume massivo de dados e alertas gerados pelas redes corporativas modernas, o Centro de Operações de Segurança (SOC) tornou-se a primeira linha de defesa cibernética das empresas. Como cibercriminosos se aproveitam da sobrecarga de informações para camuflar invasões silenciosas, a atuação analítica e investigativa do Analista de SOC tornou-se vital para correlacionar eventos, filtrar falsos positivos e interceptar ameaças reais antes que comprometam o negócio.", "draft": false},
  {"title": "TÉCNICO EM SEGURANÇA CIBERNÉTICA", "hours": 1200, "area": "Segurança Cibernética", "justification": "Curso Técnico em Segurança Cibernética: justifica-se pelos resultados do estudo de mercado de TIC, que aponta a segurança digital e a proteção de dados como elementos estratégicos e transversais para o desenvolvimento tecnológico nos próximos anos.\n\nNesse contexto, destacam-se os seguintes aspectos:\nTecnologia estratégica e prioritária: o estudo identifica a Criptografia como uma tecnologia de tendência estratégica, fundamental para a proteção de dados e das informações digitais. A Cibersegurança também é apontada entre as áreas prioritárias para a formação de novos profissionais, evidenciando sua relevância para o setor de TIC.\nProteção dos investimentos em transformação digital: os investimentos em tecnologias como Computação em Nuvem, Inteligência Artificial e Big Data poderão alcançar aproximadamente R$ 774 bilhões até 2028. A expansão dessa infraestrutura digital amplia a necessidade de profissionais capacitados para proteger sistemas, redes, dados e serviços contra ameaças cibernéticas.\nSegurança como elemento transversal: a evolução dos ecossistemas tecnológicos, que integram IA, dados, computação em nuvem e conectividade, exige mecanismos de segurança incorporados desde a implementação até a operação das soluções. Nesse cenário, a segurança cibernética constitui uma base essencial para garantir a continuidade, a confiabilidade e a proteção dos serviços digitais.\nExpansão da Indústria 4.0 e da IoT: a integração entre ambientes físicos e digitais, por meio de sensores, redes industriais, dispositivos conectados e Edge Computing, amplia a superfície de exposição a ataques. Esse cenário requer profissionais com conhecimentos em segurança de redes, protocolos, sistemas e ambientes industriais.\n\nDessa forma, a criação do Curso Técnico em Segurança Cibernética responde à necessidade de formar profissionais capazes de atuar na proteção de dados, redes, sistemas e infraestruturas digitais, contribuindo para a segurança e a continuidade das soluções tecnológicas que sustentam a transformação digital e a evolução da Indústria 4.0.", "draft": false},
  {"title": "Desenvolvedor Associado de IA na Nuvem do Azure - AI200", "hours": 40, "area": "Cloud e DevOps", "justification": "CERTIFICAÇÃO EM NUVEM", "draft": false},
  {"title": "Desenvolvimento de Automações com IA", "hours": 60, "area": "Cloud e DevOps", "justification": "Curso abordando ferramentas de automação e IA como o n8n que estão em alta demanda.\n\nO curso Desenvolvimento de Automações com IA é essencial para capacitar profissionais na criação de soluções inteligentes que otimizam processos, aumentam a eficiência operacional e reduzem custos. A aplicação de técnicas de inteligência artificial em automações permite desenvolver sistemas adaptativos e inovadores, atendendo às demandas crescentes de transformação digital em diversos setores. Essa formação fortalece a competitividade das organizações e amplia as oportunidades de atuação dos participantes em um mercado altamente tecnológico.", "draft": false},
  {"title": "Fundamentos de Containerização", "hours": 40, "area": "Cloud e DevOps", "justification": "Aborda os fundamentos de Docker, deploy de aplicações e Compose.\n\nO curso Fundamentos de Containerização é essencial para capacitar profissionais na utilização de tecnologias modernas de empacotamento e execução de aplicações, como Docker e Kubernetes. A containerização permite maior portabilidade, escalabilidade e eficiência na gestão de ambientes computacionais, reduzindo custos e aumentando a segurança. Essa formação prepara os participantes para atender às demandas da transformação digital e da adoção de arquiteturas baseadas em microsserviços, fortalecendo sua competitividade no mercado de tecnologia.", "draft": false},
  {"title": "Kubernetes e Containerização Avançada", "hours": 60, "area": "Cloud e DevOps", "justification": "Como pré requisito deve ter o curso de Fundamentos de Containerização, aborda temas mais avançados de conteinerização e orquestração de containeres.\n\nO curso Kubernetes e Containerização Avançada é essencial para capacitar profissionais na gestão de ambientes complexos e escaláveis, utilizando práticas modernas de orquestração de containers. O domínio de Kubernetes permite automatizar deploys, balancear cargas, garantir alta disponibilidade e aplicar políticas de segurança em aplicações distribuídas. Essa formação prepara os participantes para atender às demandas da transformação digital e da adoção de arquiteturas baseadas em microsserviços, fortalecendo sua competitividade em um mercado de tecnologia altamente especializado.", "draft": false},
  {"title": "Infraestrutura como Código", "hours": 40, "area": "Cloud e DevOps", "justification": "Fundamentos de Terraform, pode ser gancho para qualquer curso de nuvem e para devs.\n\nO curso Infraestrutura como Código é essencial para capacitar profissionais na automação da criação, configuração e gerenciamento de ambientes de TI, utilizando ferramentas como Terraform e Ansible. Essa abordagem garante maior consistência, escalabilidade e segurança na operação de sistemas, reduzindo erros manuais e aumentando a eficiência. A formação prepara os participantes para atender às demandas da transformação digital e da adoção de práticas DevOps, fortalecendo sua competitividade no mercado de tecnologia.", "draft": false},
  {"title": "Fundamentos de Linux", "hours": 40, "area": "Cloud e DevOps", "justification": "Curso do básico de Linux, introduzindo o Sistema Operacional e as possibilidades de utilização.\n\nO curso Fundamentos de Linux é essencial para capacitar profissionais no uso do sistema operacional mais utilizado em servidores, ambientes de nuvem e dispositivos embarcados. O domínio dos conceitos básicos de Linux garante maior eficiência na administração de sistemas, segurança e automação de tarefas, além de preparar os participantes para atuar em projetos de tecnologia que exigem estabilidade e escalabilidade. Essa formação amplia a empregabilidade e fortalece a base para especializações avançadas em infraestrutura e desenvolvimento.", "draft": false},
  {"title": "ASSISTENTE DE BANCO DE DADOS", "hours": 160, "area": "Dados", "justification": "Grande utilização de dados nos processos organizacionais exige profissionais capacitados para organizar, consultar e manter informações de forma estruturada e confiável", "draft": false},
  {"title": "ANÁLISE E MODELAGEM DE DADOS COM POWER BI", "hours": 40, "area": "Dados", "justification": "Em um mercado altamente dinâmico e orientado a dados (Data-Driven), a capacidade de traduzir grandes volumes de informações em inteligência estratégica tornou-se uma das competências mais valiosas para as organizações. O curso de Análise e Modelagem de Dados com Power BI responde à demanda direta por profissionais capazes de transformar bases de dados brutas em relatórios visuais, dinâmicos e de alto impacto para a tomada de decisão.", "draft": false},
  {"title": "Técnico em Inteligência Artificial", "hours": 1200, "area": "Dados", "justification": "A justificativa para o curso está na identificação de alta demanda de profissionais com conhecimento nos processos relacionados a obtenção, tratamento e análise de dados e utilização das áreas da inteligência artificial dentro dos diversos segmentos industriais, evidenciado no estudo de mercado feito pela GRM (Gerência de relação de mercado) do Senai SP.\n\nNeste estudo consta o relatório Setorial da Brasscom (Associação das Empresas de Tecnologia da Informação e Comunicação e de Tecnologias Digitais) que projeta investimentos de aproximadamente R$ 774 bilhões em tecnologias de transformação digital até 2028. Entre os segmentos que deverão concentrar os maiores aportes destacam-se computação em nuvem, inteligência artificial, big data e analytics, indicando crescimento da demanda por esses profissionais.\n\nPelo cenário de utilização de tecnologias feito por estudo de caso dentro da análise de mercado do Senai SP, a empresa IFood, manteve uma trajetória acelerada de crescimento apoiada por investimentos contínuos em tecnologia, inovação, logística, inteligência artificial e expansão do ecossistema digital. O iFood anunciou seu maior ciclo de investimentos da história, com R$ 11 bilhões em investimentos diretos no Brasil entre abril de 2025 e março de 2026 direcionados para tecnologia, inteligência artificial, crédito, novos produtos e ampliação da presença de mercado. Sendo citado investimentos para inovação em processos para:\n\n- Aplicação de inteligência artificial para roteirização e otimização logística;\n- Personalização da experiência dos usuários em grande escala;\n- Sistemas avançados de recomendação e previsão de demanda;\n- Automação de processos de crédito e análise financeira para parceiros;\n- Governança estruturada para desenvolvimento e uso de inteligência artificial;\n- Uso intensivo de ciência de dados para tomada de decisão operacional.\n\nPor esse mesmo estudo de caso presente na análise de mercado do Senai SP, a empresa Totvs informa ter investido aproximadamente R$ 3 bilhões em Pesquisa e desenvolvimento nos últimos cinco anos, destinados à evolução de plataformas, computação em nuvem, inteligência artificial, analytics e novos modelos de negócios digitais. Em 2026, a empresa anunciou um novo ciclo de investimentos em inteligência artificial, incluindo aproximadamente R$ 300 milhões dedicados à plataforma LYNN e um CAPEX estimado de R$ 600 milhões em software e IA ao longo dos anos seguintes.\nSendo citado investimentos para inovação em processos para:\n\n- Aplicação de IA em processos de concessão de crédito;\n- Sistemas de detecção e prevenção de fraudes;\n- Automação de processos administrativos e financeiros;\n- Uso de inteligência artificial para suporte à tomada de decisão;\n- Integração de dados corporativos em plataformas unificadas;\n- Expansão de arquiteturas SaaS e cloud computing para escalabilidade operacional.\n\nNas considerações do estudo de mercado: A inteligência artificial, aparece como o segmento de maior dinamismo inovativo dentro das TICs (Tecnologia da Informação e Comunicação), com aplicações em aprendizado de máquina, redes neurais profundas, modelos de linguagem, visão, computacional, processamento de linguagem natural e sistemas de decisão autônoma.", "draft": false},
  {"title": "FUNDAMENTOS DE BANCO DE DADOS E SQL", "hours": 40, "area": "Dados", "justification": "Na era das decisões orientadas a dados (Data-Driven), a capacidade de consultar e estruturar informações tornou-se um requisito indispensável para o mercado. O curso de Fundamentos de Banco de Dados e SQL responde a essa demanda ao formar profissionais capazes de dominar a linguagem universal de manipulação de dados relacionais. A formação proporciona autonomia operacional, acelera a tomada de decisões e reduz gargalos técnicos, servindo como a base indispensável para carreiras em tecnologia, análise de negócios e inteligência de dados.", "draft": false},
  {"title": "Técnico em Data Science", "hours": 1200, "area": "Dados", "justification": "Crescente necessidade do mercado por profissionais capazes de transformar grandes volumes de dados brutos em informações estratégicas para a tomada de decisões", "draft": false},
  {"title": "VERSIONAMENTO COM GIT", "hours": 20, "area": "Desenvolvimento de software", "justification": "Garantir a segurança, a organização e o trabalho em equipe eficiente no desenvolvimento de projetos", "draft": false},
  {"title": "LINGUAGEM DE MARCAÇÃO E ESTILIZAÇÃO", "hours": 40, "area": "Desenvolvimento de software", "justification": "Toda interface web moderna — de portais corporativos a sistemas complexos e plataformas digitais — tem sua estrutura e visual construídos a partir de linguagens de marcação e estilização (HTML e CSS). O curso de Linguagem de Marcação e Estilização responde à constante demanda do mercado por profissionais capazes de criar e manter interfaces funcionais, atraentes e alinhadas aos padrões web.", "draft": false},
  {"title": "DESENVOLVIMENTO DE PROTÓTIPOS DE APLICAÇÕES WEB", "hours": 40, "area": "Desenvolvimento de software", "justification": "O curso Desenvolvimento de Protótipos de Aplicações Web é necessário para atender à crescente demanda por profissionais capazes de validar ideias e soluções digitais de forma rápida e eficiente. A prototipagem permite reduzir custos, otimizar tempo de desenvolvimento e melhorar a comunicação entre equipes técnicas e clientes. Além disso, capacita os participantes a utilizar ferramentas modernas e metodologias ágeis, tornando-os mais competitivos no mercado de trabalho e preparados para atuar em projetos inovadores de tecnologia.", "draft": false},
  {"title": "FUNDAMENTOS DE PROGRAMAÇÃO E LOW CODE", "hours": 40, "area": "Desenvolvimento de software", "justification": "A abertura do curso de Fundamentos de Programação e Low Code justifica-se pela necessidade de desenvolver competências digitais e de programação, proporcionando aos participantes conhecimentos básicos para criação de soluções tecnológicas. O curso também contribuirá para o uso de plataformas Low Code, promovendo maior agilidade, produtividade e inovação no desenvolvimento de aplicações.", "draft": false},
  {"title": "FRAMEWORK PARA INTERFACE WEB", "hours": 48, "area": "Desenvolvimento de software", "justification": "Necessidade de modelar sistemas de informação de forma padronizada, alinhada à arquitetura de camadas e focada na produtividade do desenvolvimento orientado a modelos", "draft": false},
  {"title": "CRIAÇÃO DE SITES COM WORDPRESS", "hours": 40, "area": "Desenvolvimento de software", "justification": "Simplificação a vida do criador de conteúdo. A plataforma oferece um painel de gerenciamento extremamente simples e intuitivo para escolher temas pré-prontos, instalar plugins e utilizar diversos recursos que facilitam a publicação de páginas na web", "draft": false},
  {"title": "CRIAÇÃO DE LOJAS VIRTUAIS COM WORDPRESS", "hours": 48, "area": "Desenvolvimento de software", "justification": "O curso Criação de Lojas Virtuais com WordPress é essencial para atender à crescente demanda por soluções de comércio eletrônico acessíveis e eficientes. O WordPress, aliado ao plugin WooCommerce, oferece uma plataforma flexível e de baixo custo para empreendedores e empresas que desejam expandir sua presença digital. A capacitação nesse tema possibilita que os participantes desenvolvam lojas virtuais completas, com gestão de produtos, pagamentos e logística, aumentando a competitividade no mercado e impulsionando oportunidades de negócios online.", "draft": false},
  {"title": "DESENVOLVIMENTO EM NODEJS", "hours": 80, "area": "Desenvolvimento de software", "justification": "No ecossistema moderno de software, o Node.js consolidou-se como a principal tecnologia para a criação de aplicações back-end rápidas, escaláveis e orientadas a eventos. O curso de Desenvolvimento em Node.js atende à altíssima demanda do mercado por profissionais capacitados na construção de APIs RESTful, microsserviços e sistemas em tempo real de alta performance.\nAo viabilizar o uso do JavaScript no servidor, a tecnologia unifica a linguagem de desenvolvimento em toda a aplicação, acelerando o tempo de entrega de produtos digitais (time-to-market) e otimizando a produtividade das equipes.", "draft": false},
  {"title": "DESENVOLVIMENTO EM C#", "hours": 40, "area": "Desenvolvimento de software", "justification": "Alta performance, controle de baixo nível sobre o hardware e versatilidade em múltiplos paradigmas de programação", "draft": false},
  {"title": "DESENVOLVIMENTO FULL STACK", "hours": 80, "area": "Desenvolvimento de software", "justification": "O curso de Desenvolvimento Full Stack justifica-se pela crescente demanda do mercado por profissionais qualificados em tecnologia. O curso busca desenvolver competências em front-end, back-end, bancos de dados e integração de sistemas, preparando os participantes para atuar no desenvolvimento de soluções digitais e ampliando suas oportunidades profissionais.", "draft": false},
  {"title": "DESENVOLVIMENTO MOBILE MULTIPLATAFORMA", "hours": 60, "area": "Desenvolvimento de software", "justification": "Com o uso massivo de smartphones, ter um aplicativo próprio tornou-se indispensável para empresas de todos os portes. O curso de Desenvolvimento Mobile Multiplataforma responde à forte demanda do mercado por profissionais capazes de criar aplicativos para Android e iOS utilizando uma única base de código.", "draft": false},
  {"title": "DESENVOLVEDOR DE APLICAÇÕES IOS", "hours": 80, "area": "Desenvolvimento de software", "justification": "O curso Desenvolvedor de Aplicações iOS é fundamental diante da alta demanda por aplicativos móveis voltados ao ecossistema Apple, que possui grande relevância no mercado global. A formação capacita profissionais a projetar, desenvolver e publicar aplicações na App Store, utilizando linguagens e ferramentas oficiais como Swift e Xcode. Isso amplia as oportunidades de atuação em empresas de tecnologia e startups, além de possibilitar que empreendedores criem soluções próprias, fortalecendo a inovação e a competitividade no setor de aplicativos móveis.", "draft": false},
  {"title": "PROGRAMAÇÃO EM C++ PARA IOT", "hours": null, "area": "Desenvolvimento de software", "justification": "O curso Programação em C++ para IoT é essencial para formar profissionais capazes de desenvolver soluções inteligentes e conectadas, utilizando uma das linguagens mais eficientes e amplamente empregadas em sistemas embarcados. A combinação de C++ com dispositivos de Internet das Coisas permite criar aplicações de alto desempenho, seguras e escaláveis, atendendo às demandas crescentes de automação, indústria 4.0 e cidades inteligentes. Essa capacitação amplia as oportunidades de atuação em setores estratégicos e impulsiona a inovação tecnológica.", "draft": false},
  {"title": "FUNDAMENTOS DE PYTHON 2", "hours": 40, "area": "Desenvolvimento de software", "justification": "CERTIFICAÇÃO", "draft": false},
  {"title": "Bacharelado em Ciência de Dados e Inteligência Artificial", "hours": null, "area": "Dados", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Tecnologia em Análise e Desenvolvimento de Sistemas – Semipresencial", "hours": null, "area": "Desenvolvimento de software", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Tecnologia em Segurança Cibernética", "hours": null, "area": "Segurança Cibernética", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Engenharia de Software", "hours": null, "area": "Desenvolvimento de software", "justification": "Formação solicitada para atender à demanda do setor de TIC; o detalhamento curricular e a carga horária serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Engenharia de Computação", "hours": null, "area": "Desenvolvimento de software", "justification": "A Engenharia de Computação é a disciplina que conecta o mundo físico ao digital, unindo os fundamentos do hardware (eletrônica) e do software (programação). A criação do curso de Engenharia de Computação responde à crescente necessidade do mercado por profissionais capazes de projetar, construir e integrar equipamentos inteligentes, microprocessadores e sistemas de computação de alta complexidade.\nA graduação oferece uma formação completa e interdisciplinar, preparando o estudante para criar tecnologias de ponta — como dispositivos para a Internet das Coisas (IoT), robótica, sistemas embarcados, redes de comunicação e infraestruturas digitais de grande escala.", "draft": false},
  {"title": "Tecnologia em Jogos Digitais", "hours": null, "area": "Desenvolvimento de software", "justification": "Atende à crescente demanda por profissionais capazes de desenvolver soluções interativas utilizando tecnologias e metodologias provenientes da indústria de jogos digitais, com aplicações em simuladores, ambientes virtuais de treinamento, educação e gamificação. O curso contribui para a formação de profissionais de TI aptos a desenvolver experiências digitais interativas, integrando programação, design, inteligência artificial, computação gráfica e tecnologias imersivas.", "draft": false},
  {"title": "Transformação Digital", "hours": null, "area": "Desenvolvimento de software", "justification": "Responde à necessidade das organizações de incorporar tecnologias digitais aos seus processos, produtos e modelos de negócio, preparando profissionais para conduzir iniciativas de transformação, inovação e modernização. A proposta está alinhada à crescente digitalização da indústria e à necessidade de profissionais capazes de integrar tecnologia, processos e estratégia empresarial.", "draft": false},
  {"title": "Cybersecurity e Gestão de Riscos", "hours": null, "area": "Segurança Cibernética", "justification": "Atende à crescente necessidade de proteção de dados, sistemas e infraestruturas digitais diante do aumento das ameaças cibernéticas, formando profissionais capazes de atuar na identificação, avaliação e tratamento de riscos. O curso contribui para o fortalecimento da segurança das organizações e para a adequação às exigências de governança, continuidade e proteção das informações.", "draft": false},
  {"title": "Data-Driven Business / Business Analytics", "hours": null, "area": "Dados", "justification": "Atende à crescente demanda por profissionais capazes de transformar dados em informações estratégicas para a tomada de decisão, apoiando organizações na análise de desempenho, identificação de oportunidades e otimização de processos. A proposta está alinhada ao uso crescente de dados e inteligência analítica como elementos fundamentais para competitividade e inovação empresarial.", "draft": false},
  {"title": "Executivo em IA e Tecnologias Emergentes para Negócios", "hours": null, "area": "Dados", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Product Management", "hours": null, "area": "Desenvolvimento de software", "justification": "A criação desse curso é amplamente justificada pela necessidade de profissionais que saibam articular e gerenciar os ecossistemas tecnológicos complexos que o relatório aponta como o futuro do mercado.", "draft": false},
  {"title": "Cloud & DevSecOps", "hours": null, "area": "Cloud e DevOps", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Cyber Security IT/OT: Defesa e Ofensiva", "hours": null, "area": "Segurança Cibernética", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Inteligência Artificial (reformular)", "hours": null, "area": "Dados", "justification": "Solicitação do Centro Universitário para a oferta desta formação; a carga horária e o detalhamento curricular serão definidos após a validação da pesquisa pública.", "draft": false},
  {"title": "Simulação Virtual e Gêmeos Digitais", "hours": null, "area": "Desenvolvimento de software", "justification": "A transformação digital na Indústria 4.0 exige que as empresas testem, otimizem e prevejam falhas em processos e equipamentos antes mesmo de sua construção ou operação física. A criação da pós-graduação em Simulação Virtual e Gêmeos Digitais responde à necessidade do mercado por especialistas capazes de criar réplicas virtuais exatas de sistemas reais (Digital Twins), acelerando a inovação e reduzindo custos operacionais.", "draft": false},
  {"title": "Engenharia de Dados & Big Data", "hours": null, "area": "Dados", "justification": "Com o grande volume de informações geradas diariamente pelas empresas, o maior desafio atual é construir infraestruturas capazes de processar esses dados com velocidade, segurança e escala. A criação da pós-graduação em Engenharia de Dados & Big Data responde à demanda do mercado por especialistas capazes de arquitetar, organizar e automatizar pipelines de dados, transformando grandes volumes brutos em ativos prontos para análise e inteligência de negócios.", "draft": false},
  {"title": "Arquitetura de Soluções em Nuvem (AWS/Azure/GCP)", "hours": null, "area": "Cloud e DevOps", "justification": "A migração das empresas para a nuvem transformou a infraestrutura digital na espinha dorsal dos negócios modernos. A criação da pós-graduação em Arquitetura de Soluções em Nuvem responde à forte demanda do mercado por especialistas capazes de projetar, integrar e gerenciar ambientes multicloud altamente seguros, escaláveis e econômicos nas maiores plataformas do mundo.", "draft": false},
  {"title": "MLOps e Engenharia de Machine Learning", "hours": null, "area": "Dados", "justification": "A criação do curso de MLOps e Engenharia de Machine Learning frente aos investimentos previstos para transformação digital. Com a Inteligência Artificial consolidada como o segmento de maior dinamismo das TICs, o curso atende diretamente ao déficit de 30,2% de profissionais qualificados no mercado.\nA formação foca em ocupações como, Cientistas de Dados e Arquitetos de Sistemas, essenciais para integrar o mundo físico ao digital na Indústria 4.0 e gerenciar o ciclo de vida de modelos de IA em escala industrial", "draft": false},
  {"title": "Governança, Risco e Compliance (GRC)", "hours": null, "area": "Segurança Cibernética", "justification": "A criação do curso de Governança, Risco e Compliance (GRC) justifica-se pela complexidade crescente de TIC. O estudo destaca que a segurança da informação e a gestão de riscos são competências críticas e transversais, essenciais para sustentar a infraestrutura digital e a Indústria 4.0.\nO curso atende diretamente à demanda por ocupações como, Engenheiros de Segurança da Informação e Gerentes de Projetos de TI, que exigem conhecimentos em governança e conformidade. Além disso, empresas referência como o iFood já priorizam a governança estruturada para o uso de IA e ciência de dados para garantir operações seguras e éticas.", "draft": false},
  {"title": "Blockchain", "hours": null, "area": "Dados", "justification": "A ocupação de Especialista de Blockchain evidencia uma demanda crescente por especialistas capazes de projetar aplicações descentralizadas e implementar contratos inteligentes. O curso foca em competências críticas de criptografia e redes distribuídas, fundamentais para garantir a segurança e a transparência dos processos na Indústria 4.0.", "draft": false},
  {"title": "UI/UX e Design de Produtos Digitais", "hours": null, "area": "Desenvolvimento de software", "justification": "A criação do curso de UI/UX e Design de Produtos Digitais justifica-se pela centralidade da experiência do usuário na transformação digital. O estudo aponta que ocupações ligadas ao design gráfico já sofrem pressão salarial, evidenciando a dificuldade das empresas em repor esses profissionais no contexto de um déficit setorial de 30,2%.\nA formação atende diretamente à necessidade de personalização em escala e inovação em produtos, competências críticas para o crescimento de ecossistemas digitais e serviços sob encomenda.", "draft": false},
  {"title": "DevSecOps e Infraestrutura Híbrida", "hours": null, "area": "Cloud e DevOps", "justification": "O curso prepara especialistas para integrar segurança ao ciclo de desenvolvimento e gerir infraestruturas complexas. Essa formação foca em ocupações como Engenheiros de Segurança da Informação e Arquitetos de Sistemas Computacionais, essenciais para sustentar a Indústria 4.0 e garantir a resiliência das operações digitais em larga escala.", "draft": false},
  {"title": "Governança, Riscos e Resiliência Cibernética", "hours": null, "area": "Segurança Cibernética", "justification": "A criação do curso de Governança, Riscos e Resiliência Cibernética é prioritária para sustentar a transformação digital prevista até 2028. Como a cibersegurança é a base da infraestrutura digital moderna, a formação foca em ocupações como Engenheiros de Segurança da Informação e Analistas de Perícia Digital, essenciais para gerir riscos na Indústria 4.0 e garantir a continuidade operacional frente a ameaças em ambientes complexos de IA e nuvem.", "draft": false},
  {"title": "FullStack", "hours": null, "area": "Desenvolvimento de software", "justification": "A criação da Pós-Graduação FullStack justifica-se pelo fato de o desenvolvimento de programas ser o maior segmento empregador do setor de TIC. A ocupação de Analista de Desenvolvimento de Sistemas é a líder absoluta na geração de novos postos, com uma média de 332 vagas mensais criadas no estado de São Paulo.", "draft": false}
]
$proposals$::jsonb) as item(
  title text,
  hours integer,
  area text,
  justification text,
  draft boolean
)
)
insert into public.course_proposals (
  title,
  workload_hours,
  mapped_areas,
  justification,
  status,
  created_by,
  submitted_at
)
select
  trim(source.title),
  source.hours,
  array[source.area],
  source.justification,
  case when source.draft then 'rascunho' else 'submetida' end::public.course_proposal_status,
  (select id from public.profiles where role in ('admin', 'gestor') order by created_at limit 1),
  case when source.draft then null else now() end
from source
where not exists (
  select 1
  from public.course_proposals existing
  where lower(existing.title) = lower(trim(source.title))
);

commit;

-- Conferência da carga.
select status, count(*) as quantidade
from public.course_proposals
group by status
order by status;